        sink: &'a StandardSink<'_, '_, M, W>,
    ) -> StandardImpl<'a, M, W> {
        StandardImpl {
            searcher: searcher,
            sink: sink,
            sunk: Sunk::empty(),
            in_color_match: Cell::new(false),
        }
    }

