/// the field separator.)
fn write_path_field(&self, field_separator: &[u8]) -> io::Result<()> {
    if let Some(path) = self.path() {
        self.write_spec(self.config().colors.path(), path.as_bytes())?;
        if let Some(term) = self.config().path_terminator {
            self.write(&[term])?;
        } else {
